// Merge the explicit replacement categories generated by v2fly into the baseline.
package main

import (
	"fmt"
	"os"
	"strings"

	"github.com/metacubex/mihomo/component/geodata/router"
	"google.golang.org/protobuf/proto"
)

func main() {
	if len(os.Args) != 4 {
		fmt.Fprintln(os.Stderr, "usage: merge-geosite BASE GENERATED OUTPUT")
		os.Exit(2)
	}
	if err := run(os.Args[1], os.Args[2], os.Args[3]); err != nil {
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}
}

func load(path string) (*router.GeoSiteList, error) {
	b, err := os.ReadFile(path)
	if err != nil {
		return nil, err
	}
	var list router.GeoSiteList
	if err := proto.Unmarshal(b, &list); err != nil {
		return nil, err
	}
	return &list, nil
}

func run(base, generated, output string) error {
	old, err := load(base)
	if err != nil {
		return err
	}
	fresh, err := load(generated)
	if err != nil {
		return err
	}
	wanted := strings.Fields("CN STEAM ONEDRIVE MICROSOFT CATEGORY-NETDISK-!CN CATEGORY-GAMES-!CN CATEGORY-GAMES CATEGORY-ENTERTAINMENT CATEGORY-COMPANIES CATEGORY-ADS CATEGORY-ADS-ALL CATEGORY-ADS-AND-TELEMETRY CATEGORY-TELEMETRY GEOLOCATION-!CN TRACKER GFW GOOGLE-CN APPLE-CN")
	replacements := make(map[string]*router.GeoSite, len(wanted))
	for _, name := range wanted {
		replacements[name] = nil
	}
	for _, item := range fresh.Entry {
		if _, ok := replacements[item.CountryCode]; ok {
			if replacements[item.CountryCode] != nil {
				return fmt.Errorf("duplicate generated category %s", item.CountryCode)
			}
			replacements[item.CountryCode] = item
		}
	}
	for _, name := range wanted {
		if replacements[name] == nil {
			return fmt.Errorf("missing generated category %s", name)
		}
	}
	seen := make(map[string]bool)
	for i, item := range old.Entry {
		replacement, ok := replacements[item.CountryCode]
		if !ok {
			continue
		}
		if seen[item.CountryCode] {
			return fmt.Errorf("duplicate baseline category %s", item.CountryCode)
		}
		old.Entry[i] = replacement
		seen[item.CountryCode] = true
	}
	for _, name := range wanted {
		if !seen[name] {
			return fmt.Errorf("missing baseline category %s", name)
		}
	}
	b, err := (proto.MarshalOptions{Deterministic: true}).Marshal(old)
	if err != nil {
		return err
	}
	return os.WriteFile(output, b, 0600)
}
